# Let me try a completely different approach
# For each color in the pattern, find:
# - min row, max row
# - min col, max col
# Then map to island regions

def cluster_colors(grid):
    """Find all colored (non-zero, non-background) cells grouped by color"""
    import collections
    colors = collections.defaultdict(list)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and grid[r][c] != 8:
                colors[grid[r][c]].append((r, c))
    return colors

def get_extremes(cells):
    """Get min/max row and col for a set of cells"""
    if not cells:
        return None
    rows = [r for r, c in cells]
    cols = [c for r, c in cells]
    return {
        'min_row': min(rows),
        'max_row': max(rows),
        'min_col': min(cols),
        'max_col': max(cols),
        'span_row': max(rows) - min(rows),
        'span_col': max(cols) - min(cols)
    }

def identify_island_subregions(grid):
    """Identify what subregions exist in the island"""
    rows = len(grid)
    cols = len(grid[0])

    # Find the island extent
    island_cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and grid[r][c] != 8:
                island_cells.append((r, c))

    if not island_cells:
        return None

    min_r, max_r = min(r for r, c in island_cells), max(r for r, c in island_cells)
    min_c, max_c = min(c for r, c in island_cells), max(c for r, c in island_cells)

    # Now identify distinct color blocks
    # We'll scan row by row and group consecutive identical cells
    blocks = []
    current_block = []
    current_color = None
    current_color_rows = set()

    for r in range(rows):
        cell_colors = [(c, grid[r][c]) for c in range(cols) if grid[r][c] not in (0, 8)]
        if not cell_colors:
            continue

        if cell_colors and cell_colors[0][1] != current_color:
            # Save previous block if it's a "complete" one
            if current_block and current_color and len(current_color_rows) > 0:
                blocks.append((current_color, list(current_color_rows)))
            current_block = cell_colors
            current_color = cell_colors[0][1]
            current_color_rows = set(c for c, _ in current_block)
        else:
            current_color_rows.update(c for c, _ in current_block)

        # Check if this row continues the block
        if cell_colors and (c + 1, grid[r][c + 1]) in cell_colors or (len(cell_colors) < 2 and cell_colors):
            pass

    return blocks

# Simpler: just identify regions by different color combinations

def count_colors_per_row(grid):
    """Count what colors appear in each row of the island region"""
    rows = len(grid)
    cols = len(grid[0])

    # Find island row range
    island_rows = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and grid[r][c] != 8:
                island_rows.add(r)

    if not island_rows:
        return {}

    min_r, max_r = min(island_rows), max(island_rows)

    result = {}
    for r in range(min_r, max_r + 1):
        colors_in_row = set()
        for c in range(cols):
            if grid[r][c] != 0 and grid[r][c] != 8:
                colors_in_row.add(grid[r][c])
        result[r] = colors_in_row

    return result

